  let frequency = u.frequency.x;
  let centerUv  = u.centerPoint.xy / 100.0;
  let warpMode  = i32(u.warpMode.x + 0.5);

  let uv       = contentUv;
  let relUv    = uv - centerUv;
  let dist     = length(relUv);
  let scaledA  = amplitude * 5.0;
  let scaledF  = frequency * 2.0;
