  let duvdx = vec2f(1.0 / outputWidth, 0.0);
  let duvdy = vec2f(0.0, 1.0 / outputHeight);

  let wc   = computeWarpedUv(outUv);
  let wcx  = computeWarpedUv(outUv + duvdx);
  let wcy  = computeWarpedUv(outUv + duvdy);

