  let gx = (wcx - wc) * vec2f(inputWidth, inputHeight);
  let gy = (wcy - wc) * vec2f(inputWidth, inputHeight);
  let footprint = max(length(gx), length(gy));
  let MAX_GRID = 6;
  let N = clamp(i32(ceil(footprint)), 1, MAX_GRID);
  let fN = f32(N);

